		case arg == "--list" || arg == "-l":
			flagList = true
		case arg == "--path" || arg == "-p":
			if i+1 < len(args) {
				i++
				flagPath = args[i]
			}
		case strings.HasPrefix(arg, "--path="):
			flagPath = strings.TrimPrefix(arg, "--path=")
		case strings.HasPrefix(arg, "-p") && len(arg) > 2:
			flagPath = arg[2:]
		case arg == "--regex" || arg == "-r":
			flagRegex = true
		case arg == "--rm":
			hasRemove = true
			if i+1 < len(args) {
				i++
				flagRemove = args[i]
			}
		case strings.HasPrefix(arg, "--rm="):
			hasRemove = true
			flagRemove = strings.TrimPrefix(arg, "--rm=")
		case arg == "--search" || arg == "-s":
			hasSearch = true
			if i+1 < len(args) {
				i++
				flagSearch = args[i]
			}
		case strings.HasPrefix(arg, "--search="):
			hasSearch = true
			flagSearch = strings.TrimPrefix(arg, "--search=")
		case strings.HasPrefix(arg, "-s") && len(arg) > 2:
			hasSearch = true
			flagSearch = arg[2:]
		case arg == "--tag" || arg == "-t":
			if i+1 < len(args) {
				i++
				flagTag = args[i]
			}
		case strings.HasPrefix(arg, "--tag="):
			flagTag = strings.TrimPrefix(arg, "--tag=")
		case strings.HasPrefix(arg, "-t") && len(arg) > 2:
			flagTag = arg[2:]
		case arg == "--tags" || arg == "-T":
			flagTags = true
		case arg == "--update" || arg == "-u":
			flagUpdate = true
		case arg == "--version" || arg == "-v":
			flagVersion = true
		case strings.HasPrefix(arg, "-"):
			fmt.Fprintf(os.Stderr, "unknown flag: %s\n", arg)
			os.Exit(1)
		default:
			positional = arg
		}
		i++
	}

	// Suppress unused variable warnings
	_ = flagAll

	// Handle --version
	if flagVersion {
		fmt.Println(version)
		return
	}

	// Handle --init
	if flagInit {
		fmt.Print(getDefaultConfig())
		return
	}

	// Handle --completion
	if hasCompletion {
		script, err := generateCompletion(flagCompletion)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		fmt.Print(script)
		return
	}

	// Handle --help (or no arguments and no other flags)
	noActionFlags := !flagBrief && !flagColorize && !flagConf && !flagDirectories &&
		!hasEdit && !flagList && !flagRegex && !hasRemove && !hasSearch &&
		!flagTags && !flagUpdate && positional == "" && flagPath == "" && flagTag == ""

	if flagHelp || noActionFlags {
		printHelp()
		return
	}

	// Load config
	cfg, configPath, err := loadConfig()
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	// Handle --conf
	if flagConf {
		fmt.Println(configPath)
		return
	}

	// Load cheatsheets
	sheets, warnings := loadSheets(cfg, flagPath, flagTag)
	for _, w := range warnings {
		fmt.Fprintln(os.Stderr, w)
	}

	// Handle --update
	if flagUpdate {
		updatePaths(cfg, flagPath)
		return
	}

	// Handle --directories
	if flagDirectories {
		printDirectories(cfg)
		return
	}

	// Handle --tags
	if flagTags {
		printAllTags(sheets)
		return
	}

	// Handle --list
	if flagList || (flagTag != "" && positional == "" && !hasSearch && !flagBrief) {
		printList(sheets, false)
		return
	}

	// Handle --brief
	if flagBrief {
		printBrief(sheets, positional)
		return
	}

	// Handle --search
	if hasSearch {
		results := searchSheets(sheets, flagSearch, flagRegex)
		if len(results) == 0 {
			os.Exit(2)
		}
		printSearchResults(results, flagColorize, cfg)
		return
	}

	// Handle --rm
	if hasRemove {
		err := removeSheet(sheets, flagRemove)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(2)
		}
		return
	}

	// Handle --edit
	if hasEdit {
		err := editSheet(cfg, sheets, flagEdit, flagPath)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		return
	}

	// View a cheatsheet
	if positional != "" {
		err := viewSheet(sheets, positional, flagColorize, cfg)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(2)
		}
		return
	}

	// Default: show help
	printHelp()
}

func printHelp() {
	fmt.Print(`cheat allows you to create and view interactive cheatsheets on the
command-line. It was designed to help remind *nix system administrators of
options for commands that they use frequently, but not frequently enough to
remember.

Usage:
  cheat [cheatsheet] [flags]

Examples:
  To initialize a config file:
    mkdir -p ~/.config/cheat && cheat --init > ~/.config/cheat/conf.yml

  To view the tar cheatsheet:
    cheat tar

  To edit (or create) the foo cheatsheet:
    cheat -e foo

  To edit (or create) the foo/bar cheatsheet on the "work" cheatpath:
    cheat -p work -e foo/bar

  To view all cheatsheet directories:
    cheat -d

  To list all available cheatsheets:
    cheat -l

  To briefly list all cheatsheets whose titles match "apt":
    cheat -b apt

  To list all tags in use:
    cheat -T

  To list available cheatsheets that are tagged as "personal":
    cheat -l -t personal

  To search for "ssh" among all cheatsheets, and colorize matches:
    cheat -c -s ssh

  To search (by regex) for cheatsheets that contain an IP address:
    cheat -c -r -s '(?:[0-9]{1,3}\.){3}[0-9]{1,3}'

  To remove (delete) the foo/bar cheatsheet:
    cheat --rm foo/bar

  To update all git-backed cheatpaths:
    cheat --update

  To view the configuration file path:
    cheat --conf

  To generate shell completions (bash, zsh, fish, powershell):
    cheat --completion bash

Flags:
  -a, --all                Search among all cheatpaths
  -b, --brief              List cheatsheets without file paths
  -c, --colorize           Colorize output
      --completion shell   Generate shell completion script (shell: bash, zsh, fish, powershell)
      --conf               Display the config file path
  -d, --directories        List cheatsheet directories
  -e, --edit cheatsheet    Edit cheatsheet
  -h, --help               help for cheat
      --init               Write a default config file to stdout
  -l, --list               List cheatsheets
  -p, --path name          Return only sheets found on cheatpath name
  -r, --regex              Treat search <phrase> as a regex
      --rm cheatsheet      Remove (delete) cheatsheet
  -s, --search phrase      Search cheatsheets for phrase
  -t, --tag tag            Return only sheets matching tag
  -T, --tags               List all tags in use
  -u, --update             Update git-backed cheatpaths
  -v, --version            Print the version number
`)
}

func getDefaultConfig() string {
	homeDir, _ := os.UserHomeDir()
	return fmt.Sprintf(`---
# The editor to use with 'cheat -e <sheet>'. Overridden by $VISUAL or $EDITOR.
editor: EDITOR_PATH

# Should 'cheat' always colorize output?
colorize: false

# Which 'chroma' colorscheme should be applied to the output?
# Options are available here:
#   https://github.com/alecthomas/chroma/tree/master/styles
style: monokai

# Which 'chroma' "formatter" should be applied?
# One of: "terminal", "terminal256", "terminal16m"
formatter: terminal256

# Through which pager should output be piped?
# 'less -FRX' is recommended on Unix systems
# 'more' is recommended on Windows
pager: cat

# The paths at which cheatsheets are available. Tags associated with a cheatpath
# are automatically attached to all cheatsheets residing on that path.
#
# Whenever cheatsheets share the same title (like 'tar'), the most local
# cheatsheets (those which come later in this file) take precedence over the
# less local sheets. This allows you to create your own "overides" for
# "upstream" cheatsheets.
#
# But what if you want to view the "upstream" cheatsheets instead of your own?
# Cheatsheets may be filtered by 'tags' in combination with the '--tag' flag.
# 
# Example: 'cheat tar --tag=community' will display the 'tar' cheatsheet that
# is tagged as 'community' rather than your own.
#
# Paths that come earlier are considered to be the most "global", and paths
# that come later are considered to be the most "local". The most "local" paths
# take precedence.
#
# See: https://github.com/cheat/cheat/blob/master/doc/cheat.1.md#cheatpaths
cheatpaths:

  # Cheatsheets that are tagged "personal" are stored here by default:
  - name: personal
    path: %s/.config/cheat/cheatsheets/personal
    tags: [ personal ]
    readonly: false

  # Cheatsheets that are tagged "work" are stored here by default:
  - name: work
    path: %s/.config/cheat/cheatsheets/work
    tags: [ work ]
    readonly: false

  # Community cheatsheets (https://github.com/cheat/cheatsheets):
  # To install: git clone https://github.com/cheat/cheatsheets %s/.config/cheat/cheatsheets/community
  #- name: community
  #  path: %s/.config/cheat/cheatsheets/community
  #  tags: [ community ]
  #  readonly: true

  # You can also use glob patterns to automatically load cheatsheets from all
  # directories that match.
  #
  # Example: overload cheatsheets for projects under ~/src/github.com/example/*/
  #- name: example-projects
  #  path: ~/src/github.com/example/**/.cheat
  #  tags: [ example ]
  #  readonly: true
`, homeDir, homeDir, homeDir, homeDir)
}

func configPaths() []string {
	var paths []string

	// 1. CHEAT_CONFIG_PATH
	if p := os.Getenv("CHEAT_CONFIG_PATH"); p != "" {
		paths = append(paths, p)
		return paths
	}

	homeDir, _ := os.UserHomeDir()

	if runtime.GOOS == "windows" {
		// Windows paths
		if appData := os.Getenv("APPDATA"); appData != "" {
			paths = append(paths, filepath.Join(appData, "cheat", "conf.yml"))
		}
		if progData := os.Getenv("PROGRAMDATA"); progData != "" {
			paths = append(paths, filepath.Join(progData, "cheat", "conf.yml"))
		}
	} else {
		// Unix paths
		// 2. XDG_CONFIG_HOME
		if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
			paths = append(paths, filepath.Join(xdg, "cheat", "conf.yml"))
		}
		// 3. $HOME/.config/cheat/conf.yml
		paths = append(paths, filepath.Join(homeDir, ".config", "cheat", "conf.yml"))
		// 4. $HOME/.cheat/conf.yml
		paths = append(paths, filepath.Join(homeDir, ".cheat", "conf.yml"))
		// 5. /etc/cheat/conf.yml
		paths = append(paths, "/etc/cheat/conf.yml")
	}

	return paths
}

func loadConfig() (*Config, string, error) {
	paths := configPaths()

	for _, p := range paths {
		if _, err := os.Stat(p); err == nil {
			cfg, err := parseConfig(p)
			if err != nil {
				return nil, "", err
			}
			return cfg, p, nil
		}
	}

	// No config found - run installer
	err := runInstaller()
	if err != nil {
		return nil, "", err
	}

	// Try loading again
	for _, p := range paths {
		if _, err := os.Stat(p); err == nil {
			cfg, err := parseConfig(p)
			if err != nil {
				return nil, "", err
			}
			return cfg, p, nil
		}
	}

	return nil, "", fmt.Errorf("failed to load config")
}

func prompt(question string) (string, error) {
	fmt.Fprint(os.Stdout, question)
	reader := bufio.NewReader(os.Stdin)
	answer, err := reader.ReadString('\n')
	if err != nil {
		return "", fmt.Errorf("failed to prompt: %w", err)
	}
	return strings.TrimSpace(answer), nil
}

func runInstaller() error {
	fmt.Fprint(os.Stdout, "A config file was not found. Would you like to create one now? [Y/n]: ")
	reader := bufio.NewReader(os.Stdin)
	answer, err := reader.ReadString('\n')
	if err != nil {
		return fmt.Errorf("failed to create config: failed to prompt: %w", err)
	}
	answer = strings.TrimSpace(answer)

	if answer == "n" || answer == "N" {
		return nil
	}

	// Ask about community cheatsheets
	fmt.Fprint(os.Stdout, "Would you like to download the community cheatsheets? [Y/n]: ")
	communityAnswer, err := reader.ReadString('\n')
	if err != nil {
		return fmt.Errorf("failed to run installer: failed to prompt: failed to prompt: %w", err)
	}
	communityAnswer = strings.TrimSpace(communityAnswer)

	homeDir, _ := os.UserHomeDir()
	configDir := filepath.Join(homeDir, ".config", "cheat")
	configPath := filepath.Join(configDir, "conf.yml")

	// Create config directory
	if err := os.MkdirAll(configDir, 0755); err != nil {
		return fmt.Errorf("failed to run installer: failed to create config dir: %w", err)
	}

	// Create cheatsheet directories
	personalDir := filepath.Join(configDir, "cheatsheets", "personal")
	workDir := filepath.Join(configDir, "cheatsheets", "work")
	os.MkdirAll(personalDir, 0755)
	os.MkdirAll(workDir, 0755)

	// Optionally clone community sheets
	if communityAnswer != "n" && communityAnswer != "N" {
		communityDir := filepath.Join(configDir, "cheatsheets", "community")
		fmt.Printf("Cloning community cheatsheets to %s.\n", communityDir)
		cmd := exec.Command("git", "clone", "https://github.com/cheat/cheatsheets", communityDir)
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		if err := cmd.Run(); err != nil {
			return fmt.Errorf("failed to run installer: failed to clone cheatsheets: failed to clone cheatsheets: %w", err)
		}
	}

	// Write config file
	if err := os.WriteFile(configPath, []byte(getDefaultConfig()), 0644); err != nil {
		return fmt.Errorf("failed to run installer: failed to write config: %w", err)
	}

	fmt.Printf("Created config file: %s\n", configPath)
	fmt.Println("Please read this file for advanced configuration information.")

	return nil
}

// Minimal YAML parser for cheat config
func parseConfig(path string) (*Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("failed to read config: %w", err)
	}

	cfg := &Config{
		Style:     "monokai",
		Formatter: "terminal256",
		Pager:     "cat",
	}

	return parseConfigYAML(string(data), cfg)
}

func parseConfigYAML(data string, cfg *Config) (*Config, error) {
	lines := strings.Split(data, "\n")

	// Simple YAML parser for our specific config format
	inCheatpaths := false
	currentPath := (*Cheatpath)(nil)

	for _, line := range lines {
		// Skip document markers
		if strings.TrimSpace(line) == "---" {
			continue
		}

		// Skip comments
		stripped := strings.TrimSpace(line)
		if strings.HasPrefix(stripped, "#") {
			continue
		}

		// Detect indentation level
		indent := len(line) - len(strings.TrimLeft(line, " "))

		if indent == 0 {
			// Top-level keys
			if strings.HasPrefix(stripped, "editor:") {
				cfg.Editor = parseYAMLString(strings.TrimPrefix(stripped, "editor:"))
			} else if strings.HasPrefix(stripped, "colorize:") {
				val := strings.TrimSpace(strings.TrimPrefix(stripped, "colorize:"))
				cfg.Colorize = val == "true"
			} else if strings.HasPrefix(stripped, "style:") {
				cfg.Style = parseYAMLString(strings.TrimPrefix(stripped, "style:"))
			} else if strings.HasPrefix(stripped, "formatter:") {
				cfg.Formatter = parseYAMLString(strings.TrimPrefix(stripped, "formatter:"))
			} else if strings.HasPrefix(stripped, "pager:") {
				cfg.Pager = parseYAMLString(strings.TrimPrefix(stripped, "pager:"))
			} else if strings.HasPrefix(stripped, "cheatpaths:") {
				inCheatpaths = true
			}
		} else if inCheatpaths && indent >= 2 {
			if indent == 2 && stripped == "-" {
				// New path entry
				if currentPath != nil {
					cfg.Cheatpaths = append(cfg.Cheatpaths, *currentPath)
				}
				currentPath = &Cheatpath{}
			} else if indent == 2 && strings.HasPrefix(stripped, "- ") {
				// New path entry with inline content
				if currentPath != nil {
					cfg.Cheatpaths = append(cfg.Cheatpaths, *currentPath)
				}
				currentPath = &Cheatpath{}
				rest := strings.TrimPrefix(stripped, "- ")
				parseCheatpathField(currentPath, rest)
			} else if indent >= 4 && currentPath != nil {
				parseCheatpathField(currentPath, stripped)
			}
		}
	}

	if currentPath != nil {
		cfg.Cheatpaths = append(cfg.Cheatpaths, *currentPath)
	}

	return cfg, nil
}

func parseCheatpathField(cp *Cheatpath, s string) {
	if strings.HasPrefix(s, "name:") {
		cp.Name = parseYAMLString(strings.TrimPrefix(s, "name:"))
	} else if strings.HasPrefix(s, "path:") {
		cp.Path = parseYAMLString(strings.TrimPrefix(s, "path:"))
	} else if strings.HasPrefix(s, "readonly:") {
		val := strings.TrimSpace(strings.TrimPrefix(s, "readonly:"))
		cp.Readonly = val == "true"
	} else if strings.HasPrefix(s, "tags:") {
		tagsStr := strings.TrimSpace(strings.TrimPrefix(s, "tags:"))
		cp.Tags = parseYAMLList(tagsStr)
	}
}

func parseYAMLString(s string) string {
	s = strings.TrimSpace(s)
	// Remove surrounding quotes
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'') {
			return s[1 : len(s)-1]
		}
	}
	return s
}

func parseYAMLList(s string) []string {
	// Format: [ item1, item2 ] or just "item1, item2"
	s = strings.TrimSpace(s)
	if strings.HasPrefix(s, "[") && strings.HasSuffix(s, "]") {
		s = s[1 : len(s)-1]
	}
	parts := strings.Split(s, ",")
	var result []string
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p != "" {
			result = append(result, p)
		}
	}
	return result
}

func expandPath(path string) string {
	if strings.HasPrefix(path, "~/") {
		homeDir, _ := os.UserHomeDir()
		path = filepath.Join(homeDir, path[2:])
	}
	return path
}

// Load all cheatsheets from configured paths
func loadSheets(cfg *Config, filterPath, filterTag string) ([]*Sheet, []string) {
	var sheets []*Sheet
	var warnings []string

	// Find .cheat directory in cwd and ancestors
	cwd, _ := os.Getwd()
	dotCheatDir := findDotCheat(cwd)

	// Add .cheat dir as first path (most global in terms of being pre-existing paths)
	var allPaths []Cheatpath

	for _, cp := range cfg.Cheatpaths {
		if filterPath != "" && cp.Name != filterPath {
			continue
		}
		allPaths = append(allPaths, cp)
	}

	if dotCheatDir != "" && filterPath == "" {
		allPaths = append(allPaths, Cheatpath{
			Name:     ".cheat",
			Path:     dotCheatDir,
			Tags:     nil,
			Readonly: false,
		})
	}

	for _, cp := range allPaths {
		expanded := expandPath(cp.Path)

		// Check for glob pattern
		if strings.Contains(expanded, "*") {
			warnings = append(warnings, fmt.Sprintf("WARNING: cheatpath '%s' does not exist, skipping", cp.Path))
			continue
		}

		if _, err := os.Stat(expanded); err != nil {
			warnings = append(warnings, fmt.Sprintf("WARNING: cheatpath '%s' does not exist, skipping", cp.Path))
			continue
		}

		pathSheets := loadSheetsFromPath(expanded, cp, filterTag)
		sheets = append(sheets, pathSheets...)
	}

	// Sort sheets by title
	sort.Slice(sheets, func(i, j int) bool {
		if sheets[i].Title == sheets[j].Title {
			return sheets[i].PathName < sheets[j].PathName
		}
		return sheets[i].Title < sheets[j].Title
	})

	return sheets, warnings
}

func findDotCheat(dir string) string {
	for {
		candidate := filepath.Join(dir, ".cheat")
		if info, err := os.Stat(candidate); err == nil && info.IsDir() {
			return candidate
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
	return ""
}

func loadSheetsFromPath(dir string, cp Cheatpath, filterTag string) []*Sheet {
	var sheets []*Sheet

	err := filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if info.IsDir() {
			return nil
		}

		// Skip hidden files
		if strings.HasPrefix(info.Name(), ".") {
			return nil
		}

		// Compute title (relative path from dir)
		rel, _ := filepath.Rel(dir, path)
		title := rel

		// Read the file
		content, err := os.ReadFile(path)
		if err != nil {
			return nil
		}

		fm, body := parseFrontmatter(string(content))

		// Merge tags: path tags + sheet tags, sorted unique
		allTags := mergeTags(cp.Tags, fm.Tags)

		// Apply tag filter
		if filterTag != "" && !containsTag(allTags, filterTag) {
			return nil
		}

		sheet := &Sheet{
			Title:    title,
			File:     path,
			Tags:     allTags,
			Syntax:   fm.Syntax,
			Content:  body,
			Readonly: cp.Readonly,
			PathName: cp.Name,
		}
		sheets = append(sheets, sheet)
		return nil
	})
	_ = err

	return sheets
}

func mergeTags(pathTags, sheetTags []string) []string {
	seen := make(map[string]bool)
	var result []string

	all := append(pathTags, sheetTags...)
	for _, t := range all {
		if !seen[t] {
			seen[t] = true
			result = append(result, t)
		}
	}
	sort.Strings(result)
	return result
}

func containsTag(tags []string, tag string) bool {
	for _, t := range tags {
		if t == tag {
			return true
		}
	}
	return false
}

func parseFrontmatter(content string) (Frontmatter, string) {
	var fm Frontmatter

	if !strings.HasPrefix(content, "---") {
		return fm, content
	}

	// Find the closing ---
	rest := content[3:]
	// Skip the first newline
	if strings.HasPrefix(rest, "\n") {
		rest = rest[1:]
	} else if strings.HasPrefix(rest, "\r\n") {
		rest = rest[2:]
	}

	idx := strings.Index(rest, "\n---")
	if idx < 0 {
		return fm, content
	}

	yamlPart := rest[:idx]
	body := rest[idx+4:] // skip \n---

	// Skip the newline after ---
	if strings.HasPrefix(body, "\n") {
		body = body[1:]
	} else if strings.HasPrefix(body, "\r\n") {
		body = body[2:]
	}

	// Parse the YAML frontmatter
	for _, line := range strings.Split(yamlPart, "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "syntax:") {
			fm.Syntax = parseYAMLString(strings.TrimPrefix(line, "syntax:"))
		} else if strings.HasPrefix(line, "tags:") {
			fm.Tags = parseYAMLList(strings.TrimPrefix(line, "tags:"))
		}
	}

	return fm, body
}

func printDirectories(cfg *Config) {
	// Calculate max name length
	maxLen := 0
	for _, cp := range cfg.Cheatpaths {
		nameColon := cp.Name + ":"
		if len(nameColon) > maxLen {
			maxLen = len(nameColon)
		}
	}

	for _, cp := range cfg.Cheatpaths {
		nameColon := cp.Name + ":"
		expanded := expandPath(cp.Path)
		fmt.Printf("%-*s %s\n", maxLen, nameColon, expanded)
	}
}

func printAllTags(sheets []*Sheet) {
	seen := make(map[string]bool)
	for _, s := range sheets {
		for _, t := range s.Tags {
			seen[t] = true
		}
	}
	var tags []string
	for t := range seen {
		tags = append(tags, t)
	}
	sort.Strings(tags)
	for _, t := range tags {
		fmt.Println(t)
	}
}

func printList(sheets []*Sheet, brief bool) {
	// Calculate column widths
	maxTitle := len("title:")
	maxFile := len("file:")
	for _, s := range sheets {
		if len(s.Title) > maxTitle {
			maxTitle = len(s.Title)
		}
		if len(s.File) > maxFile {
			maxFile = len(s.File)
		}
	}

	// Print header
	fmt.Printf("%-*s %-*s %s\n", maxTitle, "title:", maxFile, "file:", "tags:")

	// Print rows
	for _, s := range sheets {
		tags := strings.Join(s.Tags, ",")
		fmt.Printf("%-*s %-*s %s\n", maxTitle, s.Title, maxFile, s.File, tags)
	}
}

func printBrief(sheets []*Sheet, filter string) {
	// Filter by title if filter is set
	var filtered []*Sheet
	for _, s := range sheets {
		if filter == "" || strings.Contains(s.Title, filter) {
			filtered = append(filtered, s)
		}
	}

	if len(filtered) == 0 {
		os.Exit(2)
	}

	// Calculate column widths
	maxTitle := len("title:")
	for _, s := range filtered {
		if len(s.Title) > maxTitle {
			maxTitle = len(s.Title)
		}
	}

	// Print header
	fmt.Printf("%-*s %s\n", maxTitle, "title:", "tags:")

	// Print rows
	for _, s := range filtered {
		tags := strings.Join(s.Tags, ",")
		fmt.Printf("%-*s %s\n", maxTitle, s.Title, tags)
	}
}

type SearchResult struct {
	Sheet   *Sheet
	Content string
}

func searchSheets(sheets []*Sheet, phrase string, isRegex bool) []SearchResult {
	var results []SearchResult

	for _, s := range sheets {
		matched, matchedContent := searchInSheet(s, phrase, isRegex)
		if matched {
			results = append(results, SearchResult{Sheet: s, Content: matchedContent})
		}
	}

	return results
}

func searchInSheet(s *Sheet, phrase string, isRegex bool) (bool, string) {
	lines := strings.Split(s.Content, "\n")
	var matchedLines []string

	if isRegex {
		re, err := regexp.Compile(phrase)
		if err != nil {
			return false, ""
		}
		for _, line := range lines {
			if re.MatchString(line) {
				matchedLines = append(matchedLines, line)
			}
		}
	} else {
		for _, line := range lines {
			if strings.Contains(line, phrase) {
				matchedLines = append(matchedLines, line)
			}
		}
	}

	if len(matchedLines) == 0 {
		return false, ""
	}

	return true, s.Content
}

func printSearchResults(results []SearchResult, colorize bool, cfg *Config) {
	for _, r := range results {
		// Print header
		if colorize {
			fmt.Printf("%s \x1b[2m(%s)\x1b[0m\n", r.Sheet.Title, r.Sheet.PathName)
		} else {
			fmt.Printf("%s (%s)\n", r.Sheet.Title, r.Sheet.PathName)
		}

		// Print content indented
		content := r.Content
		if colorize {
			content = colorizeContent(content, r.Sheet.Syntax, cfg)
		}

		lines := strings.Split(content, "\n")
		// Remove trailing empty lines
		for len(lines) > 0 && lines[len(lines)-1] == "" {
			lines = lines[:len(lines)-1]
		}
		for _, line := range lines {
			fmt.Printf("\t%s\n", line)
		}
	}
}

func viewSheet(sheets []*Sheet, title string, colorize bool, cfg *Config) error {
	// Find the most local sheet with the given title
	var found *Sheet
	for _, s := range sheets {
		if s.Title == title {
			found = s
		}
	}

	if found == nil {
		return fmt.Errorf("No cheatsheet found for '%s'.", title)
	}

	content := found.Content
	if colorize || cfg.Colorize {
		content = colorizeContent(content, found.Syntax, cfg)
	}

	pipeToPage(content, cfg.Pager)
	return nil
}

func pipeToPage(content, pager string) {
	if pager == "" || pager == "cat" {
		fmt.Print(content)
		return
	}

	// Run pager command
	cmd := exec.Command("sh", "-c", pager)
	cmd.Stdin = strings.NewReader(content)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Run()
}

func removeSheet(sheets []*Sheet, title string) error {
	var found *Sheet
	for _, s := range sheets {
		if s.Title == title {
			found = s
		}
	}

	if found == nil {
		return fmt.Errorf("No cheatsheet found for '%s'.", title)
	}

	return os.Remove(found.File)
}

func editSheet(cfg *Config, sheets []*Sheet, title, pathFilter string) error {
	// Find the editor
	editor := os.Getenv("VISUAL")
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		editor = cfg.Editor
	}

	// Find existing sheet or create new one
	var targetFile string

	// Look for existing sheet
	var found *Sheet
	for _, s := range sheets {
		if s.Title == title {
			found = s
		}
	}

	if found != nil {
		if found.Readonly {
			// Need to copy to writable path
			targetFile = getWritablePath(cfg, title, pathFilter)
			if targetFile == "" {
				return fmt.Errorf("no writable cheatpath available")
			}
			// Copy file
			if err := copyFile(found.File, targetFile); err != nil {
				return err
			}
		} else {
			targetFile = found.File
		}
	} else {
		// New sheet - put in writable path
		targetFile = getWritablePath(cfg, title, pathFilter)
		if targetFile == "" {
			return fmt.Errorf("no writable cheatpath available")
		}
		// Create directory if needed
		os.MkdirAll(filepath.Dir(targetFile), 0755)
	}

	// Run editor
	cmd := exec.Command(editor, targetFile)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("failed to edit cheatsheet: %w", err)
	}

	return nil
}

func getWritablePath(cfg *Config, title, pathFilter string) string {
	// Find the most local writable path
	var writablePath *Cheatpath
	for i := range cfg.Cheatpaths {
		cp := &cfg.Cheatpaths[i]
		if cp.Readonly {
			continue
		}
		if pathFilter != "" && cp.Name != pathFilter {
			continue
		}
		writablePath = cp
	}

	if writablePath == nil {
		return ""
	}

	expanded := expandPath(writablePath.Path)
	return filepath.Join(expanded, title)
}

func copyFile(src, dst string) error {
	data, err := os.ReadFile(src)
	if err != nil {
		return err
	}
	os.MkdirAll(filepath.Dir(dst), 0755)
	return os.WriteFile(dst, data, 0644)
}

func updatePaths(cfg *Config, pathFilter string) {
	hasError := false
	for _, cp := range cfg.Cheatpaths {
		if pathFilter != "" && cp.Name != pathFilter {
			continue
		}
		expanded := expandPath(cp.Path)

		// Check if it's a git repo
		gitDir := filepath.Join(expanded, ".git")
		if _, err := os.Stat(gitDir); err != nil {
			fmt.Printf("%s: skipped (not a git repository)\n", cp.Name)
			continue
		}

		// Run git pull
		cmd := exec.Command("git", "-C", expanded, "pull")
		output, err := cmd.CombinedOutput()
		if err != nil {
			fmt.Printf("%s: error (%s)\n", cp.Name, strings.TrimSpace(string(output)))
			hasError = true
		} else {
			fmt.Printf("%s: updated\n", cp.Name)
		}
	}

	if hasError {
		os.Exit(1)
	}
}

func handleComplete(args []string) {
	// Load config
	cfg, _, err := loadConfig()
	var sheets []*Sheet
	var warnings []string
	if err == nil {
		sheets, warnings = loadSheets(cfg, "", "")
		_ = warnings
	}

	// Get cheatsheet names, tags, path names
	sheetNames := getSheetNames(sheets)
	tagNames := getAllTagNames(sheets)
	pathNames := getPathNames(cfg)

	// Parse what's being completed
	// args contains the command line after "cheat"
	// Last arg is what's being completed

	if len(args) == 0 {
		printCompletions(sheetNames)
		return
	}

	// Find previous flag to determine what we're completing
	prev := ""
	if len(args) >= 2 {
		prev = args[len(args)-2]
	}

	switch prev {
	case "--tag", "-t":
		printCompletions(tagNames)
	case "--path", "-p":
		printCompletions(pathNames)
	case "--search", "-s":
		// No completions for search phrase
		fmt.Println(":0")
		return
	case "--edit", "-e":
		printCompletions(sheetNames)
	case "--rm":
		printCompletions(sheetNames)
	case "--completion":
		// Default file completion
		fmt.Println(":0")
		return
	default:
		// Check if the last arg is a flag expecting a value
		last := args[len(args)-1]
		if last == "--tag" || last == "-t" {
			printCompletions(tagNames)
		} else if last == "--path" || last == "-p" {
			printCompletions(pathNames)
		} else if last == "--search" || last == "-s" {
			fmt.Println(":0")
		} else if last == "--edit" || last == "-e" {
			printCompletions(sheetNames)
		} else if last == "--rm" {
			printCompletions(sheetNames)
		} else if last == "--completion" {
			fmt.Println(":0")
		} else {
			printCompletions(sheetNames)
		}
	}
}

func printCompletions(items []string) {
	for _, item := range items {
		fmt.Println(item)
	}
	fmt.Println(":4")
}

func getSheetNames(sheets []*Sheet) []string {
	seen := make(map[string]bool)
	var names []string
	for _, s := range sheets {
		if !seen[s.Title] {
			seen[s.Title] = true
			names = append(names, s.Title)
		}
	}
	sort.Strings(names)
	return names
}

func getAllTagNames(sheets []*Sheet) []string {
	seen := make(map[string]bool)
	for _, s := range sheets {
		for _, t := range s.Tags {
			seen[t] = true
		}
	}
	var tags []string
	for t := range seen {
		tags = append(tags, t)
	}
	sort.Strings(tags)
	return tags
}

func getPathNames(cfg *Config) []string {
	if cfg == nil {
		return nil
	}
	var names []string
	for _, cp := range cfg.Cheatpaths {
		names = append(names, cp.Name)
	}
	return names
}

func generateCompletion(shell string) (string, error) {
	switch shell {
	case "bash":
		return bashCompletion, nil
	case "zsh":
		return zshCompletion, nil
	case "fish":
		return fishCompletion, nil
	case "powershell":
		return powershellCompletion, nil
	default:
		return "", fmt.Errorf("unsupported shell: %s (valid: bash, zsh, fish, powershell)", shell)
	}
}

// Syntax highlighting
func colorizeContent(content, syntax string, cfg *Config) string {
	if syntax == "" {
		syntax = "bash"
	}
	return highlightContent(content, syntax, cfg.Style, cfg.Formatter)
}

