func printBrief(sheets []*Sheet, filter string) {
	var filtered []*Sheet
	for _, s := range sheets {
		if filter == "" || strings.Contains(s.Title, filter) {
			filtered = append(filtered, s)
		}
	}

	if len(filtered) == 0 {
		os.Exit(2)
	}

	maxTitle := len("title:")
	for _, s := range filtered {
		if len(s.Title) > maxTitle {
			maxTitle = len(s.Title)
		}
	}

	fmt.Printf("%-*s %s\n", maxTitle, "title:", "tags:")

	for _, s := range filtered {
		tags := strings.Join(s.Tags, ",")
		fmt.Printf("%-*s %s\n", maxTitle, s.Title, tags)
