	paths := configPaths()

	for _, p := range paths {
		if _, err := os.Stat(p); err == nil {
			cfg, err := parseConfig(p)
			if err != nil {
				return nil, "", err
			}
			return cfg, p, nil
		}
	}

	// No config found - run installer
	err := runInstaller()
	if err != nil {
		return nil, "", err
	}

	// Try loading again
	for _, p := range paths {
		if _, err := os.Stat(p); err == nil {
			cfg, err := parseConfig(p)
			if err != nil {
				return nil, "", err
			}
			return cfg, p, nil
		}
	}

	return nil, "", fmt.Errorf("failed to load config")
