	fmt.Fprint(os.Stdout, "Would you like to download the community cheatsheets? [Y/n]: ")
	communityAnswer, err := reader.ReadString('\n')
	if err != nil {
		return fmt.Errorf("failed to run installer: failed to prompt: failed to prompt: %w", err)
	}
	communityAnswer = strings.TrimSpace(communityAnswer)

	homeDir, _ := os.UserHomeDir()
	configDir := filepath.Join(homeDir, ".config", "cheat")
	configPath := filepath.Join(configDir, "conf.yml")

	if err := os.MkdirAll(configDir, 0755); err != nil {
		return fmt.Errorf("failed to run installer: failed to create config dir: %w", err)
	}

	personalDir := filepath.Join(configDir, "cheatsheets", "personal")
	workDir := filepath.Join(configDir, "cheatsheets", "work")
	os.MkdirAll(personalDir, 0755)
	os.MkdirAll(workDir, 0755)

	if communityAnswer != "n" && communityAnswer != "N" {
		communityDir := filepath.Join(configDir, "cheatsheets", "community")
		fmt.Printf("Cloning community cheatsheets to %s.\n", communityDir)
		cmd := exec.Command("git", "clone", "https://github.com/cheat/cheatsheets", communityDir)
		cmd.Stdout = os.Stdout
