func highlightContent(content, syntax, style, formatter string) string {
	if style != "monokai" {
		style = "monokai"
	}

	tokens := tokenize(content, syntax)
	return renderTokens(tokens, style, formatter)
}

func renderTokens(tokens []Token, style, formatter string) string {
	var sb strings.Builder

	for _, tok := range tokens {
		colored := applyColor(tok.Value, tok.Type, formatter)
		sb.WriteString(colored)
	}

	return sb.String()
}

func applyColor(text string, tokenType TokenType, formatter string) string {
	if text == "" {
		return ""
	}

	switch formatter {
	case "terminal256":
		color, ok := monokai256[tokenType]
		if !ok {
			color = 231
		}
		return "\x1b[38;5;" + itoa(color) + "m" + text + "\x1b[0m"
	case "terminal16m":
		rgb, ok := monokaiRGB[tokenType]
		if !ok {
			rgb = [3]int{248, 248, 242}
		}
		return "\x1b[38;2;" + itoa(rgb[0]) + ";" + itoa(rgb[1]) + ";" + itoa(rgb[2]) + "m" + text + "\x1b[0m"
	case "terminal":
		tc, ok := monokaiTerminal[tokenType]
		if !ok {
			tc = [2]int{1, 37}
		}
		if tc[0] == 1 {
			return "\x1b[1m\x1b[" + itoa(tc[1]) + "m" + text + "\x1b[0m"
		}
		return "\x1b[" + itoa(tc[1]) + "m" + text + "\x1b[0m"
	default:
		return text
	}
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	result := ""
	for n > 0 {
		result = string(rune('0'+n%10)) + result
		n /= 10
	}
	return result
}

// Tokenizer - simple regex-based tokenizer
func tokenize(content, syntax string) []Token {
	switch strings.ToLower(syntax) {
	case "text", "plain":
		return tokenizeText(content)
	case "bash", "sh", "shell", "zsh", "":
		return tokenizeBash(content)
	case "python", "py":
		return tokenizePython(content)
	case "javascript", "js":
		return tokenizeJavaScript(content)
	case "go", "golang":
		return tokenizeGo(content)
	default:
		return tokenizeBash(content)
	}
}

func tokenizeText(content string) []Token {
	if content == "" {
		return nil
	}
	return []Token{{Type: TokenText, Value: content}}
}

// Generic tokenizer using a list of rules
type LexRule struct {
	Pattern *regexp.Regexp
	Type    TokenType
}

func applyRules(content string, rules []LexRule) []Token {
	var tokens []Token
	remaining := content

	for len(remaining) > 0 {
		matched := false
		for _, rule := range rules {
			loc := rule.Pattern.FindStringIndex(remaining)
			if loc != nil && loc[0] == 0 {
				tokens = append(tokens, Token{Type: rule.Type, Value: remaining[:loc[1]]})
				remaining = remaining[loc[1]:]
				matched = true
				break
			}
		}
		if !matched {
			// Emit single character as text
			tokens = append(tokens, Token{Type: TokenText, Value: remaining[:1]})
			remaining = remaining[1:]
		}
	}

	return tokens
}

// Bash tokenizer
var bashRules []LexRule

func init() {
	bashRules = []LexRule{
		// Shebang line
		{regexp.MustCompile(`^#![^\n]*`), TokenComment},
		// Single line comments
		{regexp.MustCompile(`^#[^\n]*`), TokenComment},
		// Double-quoted strings
		{regexp.MustCompile(`^"(?:[^"\\]|\\.)*"`), TokenString},
		// Single-quoted strings
		{regexp.MustCompile(`^'[^']*'`), TokenString},
		// $((arithmetic))
		{regexp.MustCompile(`^\$\(\(`), TokenKeyword},
		{regexp.MustCompile(`^\)\)`), TokenKeyword},
		// Keywords
		{regexp.MustCompile(`^(if|then|else|elif|fi|while|do|done|for|in|case|esac|function|select|until|return|break|continue|exit|local|export|readonly|declare|typeset|unset|shift|getopts|set|unsetopt|setopt|source|eval|exec|trap|wait|jobs|bg|fg|kill|true|false)\b`), TokenKeyword},
		// Numbers
		{regexp.MustCompile(`^\d+`), TokenNumber},
		// Operators
		{regexp.MustCompile(`^[=+\-*/%<>!&|^~\[\]]`), TokenOperator},
		// Whitespace and newlines
		{regexp.MustCompile(`^[\s]+`), TokenText},
		// Regular words
		{regexp.MustCompile(`^[a-zA-Z_$][a-zA-Z0-9_$]*`), TokenText},
		// Any other character
		{regexp.MustCompile(`^.`), TokenText},
	}
}

func tokenizeBash(content string) []Token {
	return applyRules(content, bashRules)
}

