var pythonDeclKeywords = map[string]bool{
	"def": true, "class": true,
}

var pythonRules []LexRule

func init() {
	pythonRules = []LexRule{
		// Comments
		{regexp.MustCompile(`^#[^\n]*`), TokenComment},
		// Triple-quoted strings
		{regexp.MustCompile(`^"""(?:[^"\\]|\\.|"(?!""))*"""`), TokenString},
		{regexp.MustCompile(`^'''(?:[^'\\]|\\.|'(?!''))*'''`), TokenString},
		// F-strings (simplified)
		{regexp.MustCompile(`^[fFrRbB]{0,2}"(?:[^"\\]|\\.)*"`), TokenString},
		{regexp.MustCompile(`^[fFrRbB]{0,2}'(?:[^'\\]|\\.)*'`), TokenString},
		// Numbers
		{regexp.MustCompile(`^\d+(?:\.\d+)?(?:[eE][+-]?\d+)?`), TokenNumber},
		// Identifiers/keywords
		{regexp.MustCompile(`^[a-zA-Z_]\w*`), TokenText}, // will be reclassified
		// Operators
		{regexp.MustCompile(`^[=+\-*/%<>!&|^~@]`), TokenOperator},
		// Whitespace
		{regexp.MustCompile(`^[\s]+`), TokenText},
		// Other
		{regexp.MustCompile(`^.`), TokenText},
	}
}

func tokenizePython(content string) []Token {
	raw := applyRules(content, pythonRules)
	var result []Token
	for _, tok := range raw {
		if tok.Type == TokenText {
			if pythonDeclKeywords[tok.Value] {
				tok.Type = TokenKeyword
			} else if pythonKeywords[tok.Value] {
				tok.Type = TokenKeyword
			} else if len(tok.Value) > 0 && (tok.Value[0] >= 'a' && tok.Value[0] <= 'z' || tok.Value[0] >= 'A' && tok.Value[0] <= 'Z' || tok.Value[0] == '_') {
				// Check if next non-whitespace token is '(' - it's a function
				tok.Type = TokenName
			}
		}
		result = append(result, tok)
	}
	return result
}

