			loc := rule.Pattern.FindStringIndex(remaining)
			if loc != nil && loc[0] == 0 {
				tokens = append(tokens, Token{Type: rule.Type, Value: remaining[:loc[1]]})
				remaining = remaining[loc[1]:]
				matched = true
				break
			}
		}
		if !matched {
			tokens = append(tokens, Token{Type: TokenText, Value: remaining[:1]})
			remaining = remaining[1:]
		}
	}

	return tokens
}

// Bash rules
var bashRules []LexRule

func initBashRules() {
	bashRules = []LexRule{
		{regexp.MustCompile(`(?s)^#![^\n]*`), TokenComment},
		{regexp.MustCompile(`(?s)^#[^\n]*`), TokenComment},
		{regexp.MustCompile(`^"(?:[^"\\]|\\.)*"`), TokenString},
		{regexp.MustCompile(`^'[^']*'`), TokenString},
		{regexp.MustCompile(`^\$\(\(`), TokenKeyword},
		{regexp.MustCompile(`^\)\)`), TokenKeyword},
		{regexp.MustCompile(`^(?:if|then|else|elif|fi|while|do|done|for|in|case|esac|function|select|until|return|break|continue|exit|local|export|readonly|declare|typeset|unset|shift|getopts|set|true|false|source|eval|exec|trap|wait|jobs|bg|fg|kill)\b`), TokenKeyword},
		{regexp.MustCompile(`^\d+`), TokenNumber},
		{regexp.MustCompile(`^[=+\-*/%<>!&|^~\[\]]`), TokenOperator},
		{regexp.MustCompile(`^\s+`), TokenText},
		{regexp.MustCompile(`^[a-zA-Z_$][a-zA-Z0-9_$]*`), TokenText},
		{regexp.MustCompile(`^.`), TokenText},
	}
}

func tokenizeBash(content string) []Token {
	return applyRules(content, bashRules)
}

// Python rules
var pythonRules []LexRule
var pythonKeywords = map[string]bool{
	"False": true, "None": true, "True": true, "and": true, "as": true,
	"assert": true, "async": true, "await": true, "break": true, "class": true,
	"continue": true, "def": true, "del": true, "elif": true, "else": true,
	"except": true, "finally": true, "for": true, "from": true, "global": true,
	"if": true, "import": true, "in": true, "is": true, "lambda": true,
	"nonlocal": true, "not": true, "or": true, "pass": true, "raise": true,
	"return": true, "try": true, "while": true, "with": true, "yield": true,
}

func initPythonRules() {
	pythonRules = []LexRule{
		{regexp.MustCompile(`(?s)^#[^\n]*`), TokenComment},
		// Triple-double-quoted strings
		{regexp.MustCompile(`(?s)^""".*?"""`), TokenString},
		// Triple-single-quoted strings
		{regexp.MustCompile(`(?s)^'''.*?'''`), TokenString},
		// F-strings and regular strings (double-quoted)
		{regexp.MustCompile(`^[fFrRbBuU]{0,2}"(?:[^"\\]|\\.)*"`), TokenString},
		// F-strings and regular strings (single-quoted)
		{regexp.MustCompile(`^[fFrRbBuU]{0,2}'(?:[^'\\]|\\.)*'`), TokenString},
		// Numbers
		{regexp.MustCompile(`^\d+(?:\.\d+)?(?:[eEjJ][+-]?\d+)?`), TokenNumber},
		// Identifiers
		{regexp.MustCompile(`^[a-zA-Z_]\w*`), TokenText},
		// Operators
		{regexp.MustCompile(`^[=+\-*/%<>!&|^~@]`), TokenOperator},
		{regexp.MustCompile(`^\s+`), TokenText},
		{regexp.MustCompile(`^.`), TokenText},
	}
}

func tokenizePython(content string) []Token {
	raw := applyRules(content, pythonRules)
	var result []Token
	for _, tok := range raw {
		if tok.Type == TokenText && len(tok.Value) > 0 {
			first := tok.Value[0]
			if (first >= 'a' && first <= 'z') || (first >= 'A' && first <= 'Z') || first == '_' {
				if pythonKeywords[tok.Value] {
					tok.Type = TokenKeyword
				} else {
					tok.Type = TokenName
				}
			}
		}
		result = append(result, tok)
	}
	return result
}

// JavaScript rules
var jsRules []LexRule
var jsKeywords = map[string]bool{
	"break": true, "case": true, "catch": true, "continue": true, "debugger": true,
	"default": true, "delete": true, "do": true, "else": true, "finally": true,
	"for": true, "function": true, "if": true, "in": true, "instanceof": true,
	"new": true, "return": true, "switch": true, "this": true, "throw": true,
	"try": true, "typeof": true, "var": true, "void": true, "while": true,
	"with": true, "class": true, "const": true, "enum": true, "export": true,
	"extends": true, "import": true, "super": true, "let": true, "static": true,
	"yield": true, "of": true, "from": true, "async": true, "await": true,
	"true": true, "false": true, "null": true, "undefined": true,
}

func initJSRules() {
	jsRules = []LexRule{
		{regexp.MustCompile(`(?s)^//[^\n]*`), TokenComment},
		{regexp.MustCompile(`(?s)^/\*.*?\*/`), TokenComment},
		// Template literals (backtick strings)
		{regexp.MustCompile("(?s)^`[^`]*`"), TokenString},
		{regexp.MustCompile(`^"(?:[^"\\]|\\.)*"`), TokenString},
		{regexp.MustCompile(`^'(?:[^'\\]|\\.)*'`), TokenString},
		// Numbers
		{regexp.MustCompile(`^\d+(?:\.\d+)?(?:[eE][+-]?\d+)?`), TokenNumber},
		// Identifiers
		{regexp.MustCompile(`^[a-zA-Z_$]\w*`), TokenText},
		// Arrow
		{regexp.MustCompile(`^=>`), TokenOperator},
		{regexp.MustCompile(`^[=+\-*/%<>!&|^~?:.]`), TokenOperator},
		{regexp.MustCompile(`^\s+`), TokenText},
		{regexp.MustCompile(`^.`), TokenText},
	}
}

func tokenizeJavaScript(content string) []Token {
	raw := applyRules(content, jsRules)
	var result []Token
	for _, tok := range raw {
		if tok.Type == TokenText && len(tok.Value) > 0 {
			first := tok.Value[0]
			if (first >= 'a' && first <= 'z') || (first >= 'A' && first <= 'Z') || first == '_' || first == '$' {
				if jsKeywords[tok.Value] {
					tok.Type = TokenKeyword
				} else {
					tok.Type = TokenName
				}
			}
		}
		result = append(result, tok)
	}
	return result
}

// Go rules
var goRules []LexRule
var goKeywords = map[string]bool{
	"break": true, "case": true, "chan": true, "const": true, "continue": true,
	"default": true, "defer": true, "else": true, "fallthrough": true, "for": true,
	"func": true, "go": true, "goto": true, "if": true, "interface": true,
	"map": true, "range": true, "return": true, "select": true,
	"struct": true, "switch": true, "type": true, "var": true,
}
var goNamespaceKws = map[string]bool{
	"package": true, "import": true,
}

func initGoRules() {
	goRules = []LexRule{
		{regexp.MustCompile(`(?s)^//[^\n]*`), TokenComment},
		{regexp.MustCompile(`(?s)^/\*.*?\*/`), TokenComment},
		// Raw strings (backtick)
		{regexp.MustCompile("(?s)^`[^`]*`"), TokenString},
		{regexp.MustCompile(`^"(?:[^"\\]|\\.)*"`), TokenString},
		{regexp.MustCompile(`^'(?:[^'\\]|\\.)'`), TokenString},
		// Numbers
		{regexp.MustCompile(`^\d+(?:\.\d+)?(?:[eEi][+-]?\d+)?`), TokenNumber},
		// Identifiers
		{regexp.MustCompile(`^[a-zA-Z_]\w*`), TokenText},
		// Operators
		{regexp.MustCompile(`^:=`), TokenOperator},
		{regexp.MustCompile(`^[=+\-*/%<>!&|^~]`), TokenOperator},
		{regexp.MustCompile(`^\s+`), TokenText},
		{regexp.MustCompile(`^.`), TokenText},
	}
}

func tokenizeGo(content string) []Token {
	raw := applyRules(content, goRules)
	var result []Token
	for _, tok := range raw {
		if tok.Type == TokenText && len(tok.Value) > 0 {
			first := tok.Value[0]
			if (first >= 'a' && first <= 'z') || (first >= 'A' && first <= 'Z') || first == '_' {
				if goNamespaceKws[tok.Value] {
					tok.Type = TokenKeywordNamespace
				} else if goKeywords[tok.Value] {
					tok.Type = TokenKeyword
				} else {
					tok.Type = TokenName
				}
			}
		}
		result = append(result, tok)
	}
	return result
}

func init() {
	initBashRules()
	initPythonRules()
	initJSRules()
	initGoRules()
}
