package main

import (
	"regexp"
	"strings"
)

// Token types
type TokenType int

const (
	TokenText             TokenType = iota
	TokenComment
	TokenKeyword
	TokenKeywordDecl
	TokenKeywordNamespace
	TokenString
	TokenNumber
	TokenOperator
	TokenPunctuation
	TokenName
	TokenNameFunc
	TokenNameBuiltin
)

type Token struct {
	Type  TokenType
	Value string
}

// Monokai color map for terminal256
var monokai256 = map[TokenType]int{
	TokenText:             231,
	TokenComment:          242,
	TokenKeyword:          81,
	TokenKeywordDecl:      81,
	TokenKeywordNamespace: 197,
	TokenString:           186,
	TokenNumber:           141,
	TokenOperator:         197,
	TokenPunctuation:      231,
	TokenName:             148,
	TokenNameFunc:         148,
	TokenNameBuiltin:      231,
}

// Monokai RGB colors for terminal16m
var monokaiRGB = map[TokenType][3]int{
	TokenText:             {248, 248, 242},
	TokenComment:          {117, 113, 94},
	TokenKeyword:          {102, 217, 239},
	TokenKeywordDecl:      {102, 217, 239},
	TokenKeywordNamespace: {249, 38, 114},
	TokenString:           {230, 219, 116},
	TokenNumber:           {174, 129, 255},
	TokenOperator:         {249, 38, 114},
	TokenPunctuation:      {248, 248, 242},
	TokenName:             {166, 226, 46},
	TokenNameFunc:         {166, 226, 46},
	TokenNameBuiltin:      {248, 248, 242},
}

// Terminal (16-color) bold/normal colors
var monokaiTerminal = map[TokenType][2]int{
	// [bold (0/1), color code]
	TokenText:             {1, 37},
	TokenComment:          {1, 30},
	TokenKeyword:          {0, 36},
	TokenKeywordDecl:      {0, 36},
	TokenKeywordNamespace: {1, 31},
	TokenString:           {0, 33},
	TokenNumber:           {0, 35},
	TokenOperator:         {1, 31},
	TokenPunctuation:      {1, 37},
	TokenName:             {0, 32},
	TokenNameFunc:         {0, 32},
	TokenNameBuiltin:      {1, 37},
}

func highlightContent(content, syntax, style, formatter string) string {
	tokens := tokenize(content, syntax)
	return renderTokens(tokens, formatter)
}

// Render tokens in the chroma-compatible terminal256 format
// For each token (type, value):
//   split = value.split("\n")
//   for part in split[:-1]:
//     emit color(part) + \n
//   if split[-1] != "":
//     emit color(split[-1])
func renderTokens(tokens []Token, formatter string) string {
	var sb strings.Builder

	for _, tok := range tokens {
		color := getColor256(tok.Type)

		parts := strings.Split(tok.Value, "\n")
		for i, part := range parts[:len(parts)-1] {
			_ = i
			// Emit colored part + newline
			sb.WriteString(formatColoredText(part, tok.Type, formatter, color))
			sb.WriteString("\n")
		}
		// Emit last part if non-empty
		last := parts[len(parts)-1]
		if last != "" {
			sb.WriteString(formatColoredText(last, tok.Type, formatter, color))
		}
	}

	return sb.String()
}

func getColor256(t TokenType) int {
	if c, ok := monokai256[t]; ok {
		return c
	}
	return 231
}

func formatColoredText(text string, tokenType TokenType, formatter string, color256 int) string {
	switch formatter {
	case "terminal256":
		return "\x1b[38;5;" + intToStr(color256) + "m" + text + "\x1b[0m"
	case "terminal16m":
		rgb, ok := monokaiRGB[tokenType]
		if !ok {
			rgb = [3]int{248, 248, 242}
		}
		return "\x1b[38;2;" + intToStr(rgb[0]) + ";" + intToStr(rgb[1]) + ";" + intToStr(rgb[2]) + "m" + text + "\x1b[0m"
	case "terminal":
		tc, ok := monokaiTerminal[tokenType]
		if !ok {
			tc = [2]int{1, 37}
		}
		if tc[0] == 1 {
			return "\x1b[1m\x1b[" + intToStr(tc[1]) + "m" + text + "\x1b[0m"
		}
		return "\x1b[" + intToStr(tc[1]) + "m" + text + "\x1b[0m"
	default:
		return text
	}
}

func intToStr(n int) string {
	if n == 0 {
		return "0"
	}
	result := ""
	for n > 0 {
		result = string(rune('0'+n%10)) + result
		n /= 10
	}
	return result
}

// Tokenizer
func tokenize(content, syntax string) []Token {
	switch strings.ToLower(syntax) {
	case "text", "plain", "txt":
		return tokenizeText(content)
	case "bash", "sh", "shell", "zsh", "":
		return tokenizeBash(content)
	case "python", "py":
		return tokenizePython(content)
	case "javascript", "js":
		return tokenizeJavaScript(content)
	case "go", "golang":
		return tokenizeGo(content)
	default:
		// For unknown syntax, use bash as fallback
		return tokenizeBash(content)
	}
}

// Text tokenizer - everything is plain text
func tokenizeText(content string) []Token {
	if content == "" {
		return nil
	}
	// Emit as Text but split newlines
	return []Token{{Type: TokenText, Value: content}}
}

// Line-aware tokenizer: processes line by line
// Each line's content is tokenized, then Token(Text, "\n") is appended
// Special case: hashbang includes \n in the token
func tokenizeLines(content string, lineTokenizer func(line string) []Token, isHashbang func(line string) bool) []Token {
	var tokens []Token

	// Don't split at final \n if content ends with \n
	lines := strings.Split(content, "\n")

	for i, line := range lines {
		if line == "" {
			if i < len(lines)-1 {
				// Empty line (not the last): emit Text("\n")
				tokens = append(tokens, Token{Type: TokenText, Value: "\n"})
			}
			continue
		}

		if i == 0 && isHashbang != nil && isHashbang(line) {
			// Hashbang: include \n in the token
			tokens = append(tokens, Token{Type: TokenComment, Value: line + "\n"})
			continue
		}

		// Tokenize the line
		lineTokens := lineTokenizer(line)
		tokens = append(tokens, lineTokens...)

		// Add Text("\n") after each line (except last empty line)
		if i < len(lines)-1 {
			tokens = append(tokens, Token{Type: TokenText, Value: "\n"})
		}
	}

	return tokens
}

// Bash line tokenizer
type LexRule struct {
	Pattern *regexp.Regexp
	Type    TokenType
}

var bashLineRules []LexRule

func initBashLineRules() {
	bashLineRules = []LexRule{
		// Comments (not hashbang - those are handled separately)
		{regexp.MustCompile(`^#.*`), TokenComment},
		// Double-quoted strings
		{regexp.MustCompile(`^"(?:[^"\\]|\\.)*"`), TokenString},
		// Single-quoted strings
		{regexp.MustCompile(`^'[^']*'`), TokenString},
		// $((arithmetic))
		{regexp.MustCompile(`^\$\(\(`), TokenKeyword},
		{regexp.MustCompile(`^\)\)`), TokenKeyword},
		// Keywords
		{regexp.MustCompile(`^(?:if|then|else|elif|fi|while|do|done|for|in|case|esac|function|select|until|return|break|continue|exit|local|export|readonly|declare|typeset|unset|shift|set|true|false|source|eval|exec|trap|wait|jobs|bg|fg|kill)\b`), TokenKeyword},
		// Numbers
		{regexp.MustCompile(`^\d+`), TokenNumber},
		// Single-char operators
		{regexp.MustCompile(`^[=+\-*/%<>!&|^~\[\]]`), TokenOperator},
		// Whitespace (spaces only, not newlines)
		{regexp.MustCompile(`^[^\S\n]+`), TokenText},
		// Variable references $var
		{regexp.MustCompile(`^\$[a-zA-Z_][a-zA-Z0-9_]*`), TokenText},
		// Regular words
		{regexp.MustCompile(`^[a-zA-Z_$][a-zA-Z0-9_$]*`), TokenText},
		// Any other character
		{regexp.MustCompile(`^[^\n]`), TokenText},
	}
}

func applyRulesToLine(line string, rules []LexRule) []Token {
	var tokens []Token
	remaining := line

	for len(remaining) > 0 {
		matched := false
		for _, rule := range rules {
			loc := rule.Pattern.FindStringIndex(remaining)
			if loc != nil && loc[0] == 0 {
				tokens = append(tokens, Token{Type: rule.Type, Value: remaining[:loc[1]]})
				remaining = remaining[loc[1]:]
				matched = true
				break
			}
		}
		if !matched {
			tokens = append(tokens, Token{Type: TokenText, Value: remaining[:1]})
			remaining = remaining[1:]
		}
	}

	return tokens
}

func tokenizeBashLine(line string) []Token {
	return applyRulesToLine(line, bashLineRules)
}

func tokenizeBash(content string) []Token {
	return tokenizeLines(content, tokenizeBashLine, func(line string) bool {
		return strings.HasPrefix(line, "#!")
	})
}

// Python tokenizer
var pythonLineRules []LexRule
var pythonKeywords = map[string]bool{
	"False": true, "None": true, "True": true, "and": true, "as": true,
	"assert": true, "async": true, "await": true, "break": true, "class": true,
	"continue": true, "def": true, "del": true, "elif": true, "else": true,
	"except": true, "finally": true, "for": true, "from": true, "global": true,
	"if": true, "import": true, "in": true, "is": true, "lambda": true,
	"nonlocal": true, "not": true, "or": true, "pass": true, "raise": true,
	"return": true, "try": true, "while": true, "with": true, "yield": true,
}

func initPythonLineRules() {
	pythonLineRules = []LexRule{
		{regexp.MustCompile(`^#[^\n]*`), TokenComment},
		// Triple-double-quoted strings
		{regexp.MustCompile(`(?s)^""".*?"""`), TokenString},
		{regexp.MustCompile(`(?s)^'''.*?'''`), TokenString},
		// F-strings and regular strings
		{regexp.MustCompile(`^[fFrRbBuU]{0,2}"(?:[^"\\]|\\.)*"`), TokenString},
		{regexp.MustCompile(`^[fFrRbBuU]{0,2}'(?:[^'\\]|\\.)*'`), TokenString},
		// Numbers
		{regexp.MustCompile(`^\d+(?:\.\d+)?(?:[eEjJ][+-]?\d+)?`), TokenNumber},
		// Identifiers
