// Token types
type TokenType int

const (
	TokenText             TokenType = iota
	TokenComment
	TokenKeyword
	TokenKeywordDecl
	TokenKeywordNamespace
	TokenString
	TokenNumber
	TokenOperator
	TokenPunctuation
	TokenName
	TokenNameFunc
	TokenNameBuiltin
)

type Token struct {
	Type  TokenType
	Value string
}

// Monokai color map for terminal256
var monokai256 = map[TokenType]int{
	TokenText:             231,
	TokenComment:          242,
	TokenKeyword:          81,
	TokenKeywordDecl:      81,
	TokenKeywordNamespace: 197,
	TokenString:           186,
	TokenNumber:           141,
	TokenOperator:         197,
	TokenPunctuation:      231,
	TokenName:             148,
	TokenNameFunc:         148,
	TokenNameBuiltin:      231,
}

// Monokai RGB colors for terminal16m
var monokaiRGB = map[TokenType][3]int{
	TokenText:             {248, 248, 242},
	TokenComment:          {117, 113, 94},
	TokenKeyword:          {102, 217, 239},
	TokenKeywordDecl:      {102, 217, 239},
	TokenKeywordNamespace: {249, 38, 114},
	TokenString:           {230, 219, 116},
	TokenNumber:           {174, 129, 255},
	TokenOperator:         {249, 38, 114},
	TokenPunctuation:      {248, 248, 242},
	TokenName:             {166, 226, 46},
	TokenNameFunc:         {166, 226, 46},
	TokenNameBuiltin:      {248, 248, 242},
}

// Terminal (16-color) bold/normal colors
var monokaiTerminal = map[TokenType][2]int{
	// [bold (0/1), color code]
	TokenText:             {1, 37},
	TokenComment:          {1, 30},
	TokenKeyword:          {0, 36},
	TokenKeywordDecl:      {0, 36},
	TokenKeywordNamespace: {1, 31},
	TokenString:           {0, 33},
	TokenNumber:           {0, 35},
	TokenOperator:         {1, 31},
	TokenPunctuation:      {1, 37},
	TokenName:             {0, 32},
	TokenNameFunc:         {0, 32},
	TokenNameBuiltin:      {1, 37},
}

func highlightContent(content, syntax, style, formatter string) string {
	tokens := tokenize(content, syntax)
	return renderTokens(tokens, formatter)
}

// Render tokens: for each token with value containing \n:
// Split at \n, emit colored parts with \n between, last empty part is not emitted
func renderTokens(tokens []Token, formatter string) string {
	var sb strings.Builder

	for _, tok := range tokens {
		parts := strings.Split(tok.Value, "\n")
		for _, part := range parts[:len(parts)-1] {
			// Emit colored part + newline
			sb.WriteString(formatColoredText(part, tok.Type, formatter))
			sb.WriteString("\n")
		}
		// Emit last part if non-empty
		last := parts[len(parts)-1]
		if last != "" {
			sb.WriteString(formatColoredText(last, tok.Type, formatter))
		}
	}

	return sb.String()
}

func formatColoredText(text string, tokenType TokenType, formatter string) string {
	switch formatter {
	case "terminal256":
		color, ok := monokai256[tokenType]
		if !ok {
			color = 231
		}
		return "\x1b[38;5;" + intToStr(color) + "m" + text + "\x1b[0m"
	case "terminal16m":
		rgb, ok := monokaiRGB[tokenType]
		if !ok {
			rgb = [3]int{248, 248, 242}
		}
		return "\x1b[38;2;" + intToStr(rgb[0]) + ";" + intToStr(rgb[1]) + ";" + intToStr(rgb[2]) + "m" + text + "\x1b[0m"
	case "terminal":
		tc, ok := monokaiTerminal[tokenType]
		if !ok {
			tc = [2]int{1, 37}
		}
		if tc[0] == 1 {
			return "\x1b[1m\x1b[" + intToStr(tc[1]) + "m" + text + "\x1b[0m"
		}
		return "\x1b[" + intToStr(tc[1]) + "m" + text + "\x1b[0m"
	default:
		return text
	}
}

func intToStr(n int) string {
	if n == 0 {
		return "0"
	}
	result := ""
	for n > 0 {
		result = string(rune('0'+n%10)) + result
		n /= 10
	}
	return result
}

// Tokenizer
func tokenize(content, syntax string) []Token {
	switch strings.ToLower(syntax) {
	case "text", "plain", "txt":
		return tokenizeText(content)
	case "bash", "sh", "shell", "zsh", "":
		return tokenizeBash(content)
	case "python", "py":
		return tokenizePython(content)
	case "javascript", "js":
		return tokenizeJavaScript(content)
	case "go", "golang":
		return tokenizeGo(content)
	default:
		return tokenizeBash(content)
	}
}

// Text tokenizer - everything is plain text
func tokenizeText(content string) []Token {
	if content == "" {
		return nil
	}
	return []Token{{Type: TokenText, Value: content}}
}

// mergeConsecutive merges adjacent tokens of the same type
func mergeConsecutive(tokens []Token) []Token {
	if len(tokens) == 0 {
		return nil
	}
	result := []Token{tokens[0]}
	for i := 1; i < len(tokens); i++ {
		if tokens[i].Type == result[len(result)-1].Type {
			result[len(result)-1].Value += tokens[i].Value
		} else {
			result = append(result, tokens[i])
		}
	}
	return result
}

// LexRule for character-by-character tokenization
type LexRule struct {
	Pattern *regexp.Regexp
	Type    TokenType
}

func applyRules(content string, rules []LexRule) []Token {
	var tokens []Token
	remaining := content

	for len(remaining) > 0 {
		matched := false
		for _, rule := range rules {
			loc := rule.Pattern.FindStringIndex(remaining)
			if loc != nil && loc[0] == 0 {
				tokens = append(tokens, Token{Type: rule.Type, Value: remaining[:loc[1]]})
				remaining = remaining[loc[1]:]
				matched = true
				break
			}
		}
		if !matched {
			tokens = append(tokens, Token{Type: TokenText, Value: remaining[:1]})
			remaining = remaining[1:]
		}
	}

	return mergeConsecutive(tokens)
}

// Process content line by line, applying a line tokenizer to each line
// Returns tokens with explicit Text("\n") tokens between lines
func tokenizeLines(content string, lineTokenizer func(line string) []Token, hashbangCheck func(line string) bool) []Token {
	var tokens []Token

	lines := strings.Split(content, "\n")

	for i, line := range lines {
		if i == 0 && hashbangCheck != nil && hashbangCheck(line) {
			// Hashbang: include \n in the token value
			tokens = append(tokens, Token{Type: TokenComment, Value: line + "\n"})
			continue
		}

		if line == "" {
			// Empty line
			if i < len(lines)-1 {
				tokens = append(tokens, Token{Type: TokenText, Value: "\n"})
			}
			continue
		}

		// Tokenize the line content
		lineTokens := lineTokenizer(line)
		tokens = append(tokens, lineTokens...)

		// Add newline separator (except after the last line if it's also empty)
		if i < len(lines)-1 {
			tokens = append(tokens, Token{Type: TokenText, Value: "\n"})
		}
	}

	return tokens
}

